WITH matched_keys AS (SELECT store_id FROM store_sales EXCEPT SELECT store_id FROM store_sales WHERE units > 38), kept_rows AS (SELECT s.* FROM store_sales s JOIN matched_keys k ON s.store_id = k.store_id) SELECT product_id, CASE WHEN units >= 40 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, ROUND(AVG(units), 2) AS avg_units, ROUND(AVG(units), 2) AS avg_units_2, CORR(revenue, units) AS corr_revenue_units FROM kept_rows GROUP BY ROLLUP (product_id, CASE WHEN units >= 40 THEN 'LARGE' ELSE 'SMALL' END) HAVING ROUND(AVG(units), 2) >= 0
